    # Map prime -> first index having that prime
    prime_to_index = {}

    for i, val in enumerate(nums):
        for p in prime_factors(val):
            if p in prime_to_index:
                union(i, prime_to_index[p])
            else:
                prime_to_index[p] = i

    root0 = find(0)
    for i in range(1, n):
        if find(i) != root0:
            return False
    return True

def maxIncreasingGroups(usageLimits: List[int]) -> int:
    arr = sorted(usageLimits)

    def poss(groups: int) -> bool:
        need = 1
        for v in arr:
            if v >= need:
                need += 1
                if need > groups:
                    return True
        return (need - 1) >= groups

    l, r = 0, len(arr)
    while l < r:
        mid = (l + r + 1) // 2
        if poss(mid):
            l = mid
        else:
            r = mid - 1
    return l

def maximumSum(nums: List[int]) -> int:
    n = len(nums)
    maxSum = 0
    for i in range(1, n + 1):
        total = 0
        j = 1
        while i * j * j <= n:
            nextEle = i * j * j
            total += nums[nextEle - 1]
            j += 1
        if total > maxSum:
            maxSum = total
    return maxSum

def beautifulSubstrings(s: str, k: int) -> int:
    # Step 1: determine p based on the ILR logic
    p = 1
    for i in range(1, k + 1):
        if (i * p) % k == 0:
            p = i
            break
        p = p * 2

    # Step 2: initialize data structures
    sumdict = {0: {p - 1: 1}}  # cursum -> { cate: count }
    cursum = 0
    count = 0
    vowels = {'a', 'e', 'i', 'o', 'u'}

    # Step 3: traverse the string
    for i, ch in enumerate(s):
        if ch in vowels:
            cursum += 1
        else:
            cursum -= 1

        cate = i % p

        inner = sumdict.get(cursum)
        if inner is not None and cate in inner:
            count += inner[cate]

        if inner is None:
            sumdict[cursum] = {cate: 1}
        else:
            inner[cate] = inner.get(cate, 0) + 1

    return count

def findKthSmallest(coins: List[int], k: int) -> int:
    from math import gcd

    def check(x: int) -> bool:
        total = 0
        n = len(coins)
        for mask in range(1, 1 << n):
            lcm = 1
            bits = 0
            skip = False
            for i in range(n):
                if (mask >> i) & 1:
                    bits += 1
                    g = gcd(lcm, coins[i])
                    lcm = lcm // g * coins[i]
                    if lcm > x:
                        skip = True
                        break
            if skip:
                continue
            term = x // lcm
            if bits % 2 == 1:
                total += term
            else:
                total -= term
        return total >= k

    l, r = 0, 10**18
    while l + 1 < r:
        m = (l + r) // 2
        if check(m):
            r = m
        else:
            l = m
    return r

from typing import List

def countOfPairs(nums: List[int]) -> int:
    MOD = 1_000_000_007
    n = len(nums)
    dp = [[0] * 51 for _ in range(n + 1)]
    dp[n] = [1] * 51

    for i in range(n - 1, -1, -1):
        diff = 0
        if i > 0:
            diff = max(0, nums[i] - nums[i - 1])

        for j in range(50, -1, -1):
            if j + 1 <= 50:
                dp[i][j] = dp[i][j + 1]
            else:
                dp[i][j] = 0

            if j + diff <= nums[i]:
                dp[i][j] = (dp[i][j] + dp[i + 1][j + diff]) % MOD

    return dp[0][0] % MOD

def kthCharacter( k: int, operations: List[int]) -> str:
    i = 0
    while (1 << (i + 1)) < k:
        i += 1
    count = 0
    while k > 1:
        if i < 0:
            break
        if k > (1 << i):
            if operations[i] == 1:
                count += 1
            k -= (1 << i)
            i -= 1
        else:
            i -= 1
    return chr(97 + (count % 26))
